with oracledb.connect(user=s.oracle_user,password=s.oracle_password,dsn=s.oracle_dsn)as c:
 q=c.cursor();q.execute("""select SQL_ID,EXECUTIONS,round(ELAPSED_TIME/nullif(EXECUTIONS,0)/1000,3),BUFFER_GETS,ROWS_PROCESSED from V$SQL where PARSING_SCHEMA_NAME='RABAEV' and EXECUTIONS>0 and (SQL_TEXT like 'select ''transport_cost_unrecognized'' METRIC,DOCUMENT_ID,TOTAL_COUNT%' or SQL_TEXT like 'select ''store_unloads_started'' METRIC,%') order by ELAPSED_TIME/nullif(EXECUTIONS,0)desc fetch first 10 rows only""")
 rows=q.fetchall();print(json.dumps(rows));Path('tmp/result1395.json').write_text(json.dumps(rows,indent=2),encoding='utf-8')